const response = $input.first().json;
const rows = response.data.shopifyqlQuery.tableData.rows;
const ingested_at = new Date().toISOString();
if (!rows || rows.length === 0) return [];
return rows.map(row => ({
  json: {
    ingested_at,
    store: 'store_1',
    day: row.day || null,
    session_country: row.session_country || null,
    utm_source: row.utm_source || null,
    utm_medium: row.utm_medium || null,
    utm_campaign: row.utm_campaign || null,
    sessions: parseInt(row.sessions) || 0,
    online_store_visitors: parseInt(row.online_store_visitors) || 0,
    sessions_with_cart_additions: parseInt(row.sessions_with_cart_additions) || 0,
    sessions_that_reached_checkout: parseInt(row.sessions_that_reached_checkout) || 0,
    sessions_that_completed_checkout: parseInt(row.sessions_that_completed_checkout) || 0,
    conversion_rate: parseFloat(row.conversion_rate) || 0
  }
}));

